432	    /**
433	     * Builds the customer code assigned to a newly created owner, formatted {@code '<CITY3>-<LAST3>-<NNNN>'}
434	     * where {@code CITY3} is the upper-cased first three letters of the owner's city, {@code LAST3} the
435	     * upper-cased first three letters of the owner's last name, and {@code NNNN} a per-city 4-digit
436	     * zero-padded sequence equal to one more than the number of owners already in that city (e.g.
437	     * {@code 'SYD-SMI-0007'}). The code is computed before the new owner is persisted, so the count excludes
438	     * it. Cities are matched case-insensitively so that owners sharing a {@code CITY3} prefix share a sequence.
439	     *
440	     * @param city the owner's city
441	     * @param lastName the owner's last name
442	     * @return the assigned customer code
443	     */
444	    private String generateCustomerCode(String city, String lastName) {
445	        String city3 = city.substring(0, Math.min(3, city.length())).toUpperCase(Locale.ROOT);
446	        String last3 = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase(Locale.ROOT);
447	        int sequence = (int) this.clinicService.findAllOwners().stream()
448	            .filter(existing -> city.equalsIgnoreCase(existing.getCity()))
449	            .count() + 1;
450	        return String.format("%s-%s-%04d", city3, last3, sequence);
451	    }
