469	    /**
470	     * The maximum number of owners permitted in a single city. A create request whose city already
471	     * holds this many owners is rejected.
472	     */
473	    private static final int CITY_OWNER_LIMIT = 50;
474	
475	    /**
476	     * Rejects a create request whose city already contains {@link #CITY_OWNER_LIMIT} or more owners.
477	     * Cities are matched case-insensitively, mirroring the per-city customer-code sequence, so owners
478	     * differing only in the casing of their city share one capacity pool. The count is taken before the
479	     * new owner is persisted, so it excludes the owner being created.
480	     *
481	     * @param city the city of the owner being created
482	     * @throws CityOwnerLimitExceededException if the city already holds the maximum number of owners
483	     */
484	    private void rejectCityAtCapacity(String city) {
485	        long existing = this.clinicService.findAllOwners().stream()
486	            .filter(owner -> city.equalsIgnoreCase(owner.getCity()))
487	            .count();
488	        if (existing >= CITY_OWNER_LIMIT) {
489	            throw new CityOwnerLimitExceededException(city, CITY_OWNER_LIMIT);
490	        }
491	    }
492	
493	    /**
494	     * The maximum number of owners permitted to be created in a single day. A create request whose
495	     * registration date already holds this many owners is rejected.
496	     */
497	    private static final int DAILY_OWNER_LIMIT = 100;
498	
499	    /**
500	     * Rejects a create request when {@link #DAILY_OWNER_LIMIT} or more owners have already been created
501	     * on the same day, compared by {@code registrationDate}. The count is taken before the new owner is
502	     * persisted, so it excludes the owner being created.
503	     *
504	     * @param registrationDate the registration date of the owner being created
505	     * @throws DailyOwnerLimitExceededException if the day already holds the maximum number of owners
506	     */
507	    /**
508	     * Adjusts an effective registration date so that it always falls on a business day. When the given
509	     * date is a Saturday or Sunday it is rolled forward to the following Monday; a weekday is returned
510	     * unchanged. This applies equally to a date supplied in the request and to a date defaulted to the
511	     * server date, and the adjusted value is what becomes the owner's {@code registrationDate}, so every
512	     * value derived from it (the membership number's year segment, the daily create-limit count) uses the
513	     * business-day-adjusted date.
514	     *
515	     * @param date the effective registration date, supplied or defaulted
516	     * @return the same date when it is a weekday, otherwise the next Monday
517	     */
518	    private LocalDate rollToBusinessDay(LocalDate date) {
519	        DayOfWeek day = date.getDayOfWeek();
520	        if (day == DayOfWeek.SATURDAY) {
521	            return date.plusDays(2);
522	        }
523	        if (day == DayOfWeek.SUNDAY) {
524	            return date.plusDays(1);
525	        }
526	        return date;
527	    }
528	
529	    /**
530	     * The number of owners that must already exist for a given day before a further create is flagged as a
531	     * bulk sign-up surge. When more than this many owners already share the new owner's registration date,
532	     * the created owner carries {@code bulkSignupWarning = true}.
533	     */
534	    private static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
535	
536	    /**
537	     * Determines whether the owner being created lands on a day that already holds a bulk sign-up surge,
538	     * i.e. more than {@link #BULK_SIGNUP_WARNING_THRESHOLD} owners already share its {@code registrationDate}.
539	     * The count is taken before the new owner is persisted, so it excludes the owner being created, mirroring
540	     * the daily create-limit rule's accumulation path.
541	     *
542	     * @param registrationDate the registration date of the owner being created
543	     * @return {@code true} when more than 80 owners were already created on that day, otherwise {@code false}
544	     */
545	    private boolean isBulkSignupDay(LocalDate registrationDate) {
546	        long existing = this.clinicService.findAllOwners().stream()
547	            .filter(owner -> registrationDate.equals(owner.getRegistrationDate()))
548	            .count();
549	        return existing > BULK_SIGNUP_WARNING_THRESHOLD;
550	    }
551	
552	    private void rejectDailyLimitReached(LocalDate registrationDate) {
553	        long existing = this.clinicService.findAllOwners().stream()
554	            .filter(owner -> registrationDate.equals(owner.getRegistrationDate()))
555	            .count();
556	        if (existing >= DAILY_OWNER_LIMIT) {
557	            throw new DailyOwnerLimitExceededException(registrationDate, DAILY_OWNER_LIMIT);
558	        }
559	    }
560	
561	    /**
562	     * Rejects a create request whose owner collides with an existing owner on the single derived
563	     * {@code identityKey}. This one key consolidates the former separate telephone, email and household
564	     * duplicate checks: the create is rejected only when the new owner's WHOLE identity key exactly equals
565	     * an existing owner's. Because the (normalized) telephone is part of the key, two members of the same
566	     * household (same {@code householdId}) with different telephones have different keys and are both
567	     * allowed; only an exact full-key match is a duplicate. The owner's {@code householdId} must already
568	     * have been assigned (when {@code sharesHousehold} was requested) before this check runs, so the key
569	     * compared here is the same one that is later returned.
570	     *
571	     * @param owner the owner being created, with normalized fields and any shared {@code householdId} set
572	     * @throws DuplicateIdentityException if an existing owner has the same identity key
573	     */
574	    private void rejectDuplicateIdentity(Owner owner) {
575	        String key = identityKey(owner);
576	        boolean taken = this.clinicService.findAllOwners().stream()
577	            .anyMatch(existing -> key.equals(identityKey(existing)));
578	        if (taken) {
579	            throw new DuplicateIdentityException(key);
580	        }
581	    }
582	
583	    /**
584	     * Derives an owner's {@code identityKey}: the normalized telephone, the email (or an empty string when
585	     * absent) and the household id (or an empty string when absent), joined by {@code '|'} in that order
586	     * (e.g. {@code '+61412345678||a1b2c3d4e5f6a7b8'} for an owner with no email but a shared household).
587	     * Telephone and email are stored already normalized, so the stored values are used directly.
588	     *
589	     * @param owner the owner whose identity key is being derived
590	     * @return the owner's identity key
591	     */
592	    private String identityKey(Owner owner) {
593	        String telephone = owner.getTelephone() == null ? "" : owner.getTelephone();
594	        String email = owner.getEmail() == null ? "" : owner.getEmail();
595	        String householdId = owner.getHouseholdId() == null ? "" : owner.getHouseholdId();
596	        return telephone + "|" + email + "|" + householdId;
597	    }
598	
599	    /**
600	     * Assigns the owner being created into a shared household. When at least one existing owner has the
601	     * same last name and address (compared with {@link #normalizeForComparison}), the joining owner and
602	     * those existing owners are all given the same stable {@code householdId}. An existing member's id is
603	     * reused when present; otherwise a deterministic id derived from the household's last name and address
604	     * is minted, so independently created members of the same household converge on one value. When no
605	     * existing owner shares the household, no id is assigned (the owner simply founds a new address).
606	     *
607	     * @param owner the owner being created, already opted in via {@code sharesHousehold}
608	     */
609	    private void assignHousehold(Owner owner) {
610	        String normalizedLastName = normalizeForComparison(owner.getLastName());
611	        String normalizedAddress = normalizeForComparison(owner.getAddress());
612	        List<Owner> housemates = this.clinicService.findAllOwners().stream()
613	            .filter(existing -> normalizedLastName.equals(normalizeForComparison(existing.getLastName()))
614	                && normalizedAddress.equals(normalizeForComparison(existing.getAddress())))
615	            .toList();
616	        if (housemates.isEmpty()) {
617	            return;
618	        }
619	        String householdId = housemates.stream()
620	            .map(Owner::getHouseholdId)
621	            .filter(id -> id != null && !id.isBlank())
622	            .findFirst()
623	            .orElseGet(() -> householdIdFor(normalizedLastName, normalizedAddress));
624	        owner.setHouseholdId(householdId);
625	        for (Owner housemate : housemates) {
626	            if (!householdId.equals(housemate.getHouseholdId())) {
627	                housemate.setHouseholdId(householdId);
628	                this.clinicService.saveOwner(housemate);
629	            }
630	        }
631	    }
632	
633	    /**
634	     * Derives a stable household identifier from the normalized last name and address of a household, as
635	     * the first 16 hex characters of the SHA-256 digest of {@code '<lastName>|<address>'}. The value is
636	     * deterministic, so any owner independently joining the same household computes the same identifier.
637	     *
638	     * @param normalizedLastName the household's last name, already normalized for comparison
639	     * @param normalizedAddress the household's address, already normalized for comparison
640	     * @return a stable, shareable household identifier
641	     */
642	    private String householdIdFor(String normalizedLastName, String normalizedAddress) {
643	        String key = normalizedLastName + "|" + normalizedAddress;
644	        try {
645	            byte[] digest = MessageDigest.getInstance("SHA-256")
646	                .digest(key.getBytes(StandardCharsets.UTF_8));
647	            StringBuilder sb = new StringBuilder(digest.length * 2);
648	            for (byte b : digest) {
649	                sb.append(String.format("%02x", b));
650	            }
651	            return sb.substring(0, 16);
652	        } catch (NoSuchAlgorithmException e) {
653	            throw new IllegalStateException("SHA-256 is required but unavailable", e);
654	        }
655	    }
656	
657	    /**
658	     * Normalizes a value for household-identity comparison: leading and trailing whitespace is
659	     * removed, internal runs of whitespace are collapsed to a single space, and the result is
660	     * lower-cased.
661	     *
662	     * @param value the raw value to normalize (may be {@code null})
663	     * @return the normalized value, or an empty string when {@code value} is {@code null}
664	     */
665	    private String normalizeForComparison(String value) {
666	        if (value == null) {
667	            return "";
668	        }
669	        return value.strip().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
670	    }
671	}
